"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8018],{79853:e=>{e.exports=JSON.parse('{"functions":[{"name":"Spot","desc":"The post spot for a point on the stairs: on the side edge nearest the point, moved in by\\n`inset`, and on a step at its lip, the front edge facing down the stairs, moved in by `inset` so\\nthe post stays on the step. On a ramp the spot stays where the point is along the slope; on the\\nlanding it is at the landing\'s front edge.","params":[{"name":"layout","desc":"","lua_type":"Layout"},{"name":"x","desc":"the point across the stairs","lua_type":"number"},{"name":"z","desc":"the point along them","lua_type":"number"},{"name":"inset","desc":"half a post","lua_type":"number"}],"returns":[{"desc":"the spot\'s X; nil when the point is not over the stairs","lua_type":"number?"},{"desc":"its Y","lua_type":"number"},{"desc":"its Z","lua_type":"number"}],"function_type":"static","source":{"line":41,"path":"src/Pure/StairSnap.luau"}},{"name":"FloorLines","desc":"The lines a railing on the floor around stairs lines up with, in the stairs\' frame. Across: the\\nstair railing\'s own line carried on (inside the edge) and the stairwell\'s side edges (a post\\noutside them). Along: just past the foot of the stairs and just past the top of the landing,\\nthe ends of the stairwell.","params":[{"name":"layout","desc":"","lua_type":"Layout"},{"name":"inset","desc":"how far a post\'s middle stays in from an edge","lua_type":"number"}],"returns":[{"desc":"X lines","lua_type":"{ number }"},{"desc":"Z lines","lua_type":"{ number }"}],"function_type":"static","source":{"line":78,"path":"src/Pure/StairSnap.luau"}},{"name":"Nearest","desc":"","params":[{"name":"value","desc":"","lua_type":"number"},{"name":"lines","desc":"","lua_type":"{ number }"},{"name":"reach","desc":"","lua_type":"number"}],"returns":[{"desc":"the line nearest the value, when within reach","lua_type":"number?"}],"function_type":"static","source":{"line":91,"path":"src/Pure/StairSnap.luau"}}],"properties":[],"types":[{"name":"Layout","desc":"","fields":[{"name":"Run","lua_type":"number","desc":"the depth of each step"},{"name":"Rise","lua_type":"number","desc":"the height of each step"},{"name":"Count","lua_type":"number","desc":"how many steps"},{"name":"Width","lua_type":"number","desc":""},{"name":"Landing","lua_type":"number","desc":"the depth of the top landing, 0 for none"},{"name":"Ramp","lua_type":"boolean","desc":"one smooth slope instead of steps"}],"source":{"line":23,"path":"src/Pure/StairSnap.luau"}}],"name":"StairSnap","desc":"Where a railing post stands on stairs or a ramp. Built stairs are joined into one union, so the\\nsteps are found from the layout recorded on it rather than from separate step parts.\\n\\nPositions are in the stairs\' own frame: X across (0 is the middle), Y up from the bottom, and Z\\nnegative going up the run, with 0 at the front of the first step.","source":{"line":12,"path":"src/Pure/StairSnap.luau"}}')}}]);